"use client";
import { useState } from "react";
import { Mail, MessageCircle, Linkedin, X } from "lucide-react";

export default function ContactButton() {
  const [open, setOpen] = useState(false);

  return (
    <div style={{
      position: "fixed",
      bottom: "2rem",
      right: "2rem",
      display: "flex",
      flexDirection: "column",
      gap: "6px",
      alignItems: "flex-end",
      zIndex: 1000,
      fontFamily: "var(--font-jetbrains), monospace",
    }}>

      {open && (
        <>
          {[
            { href: "mailto:y.espejo.santana@gmail.com", label: "email", prefix: "01" },
            { href: "https://wa.me/34722332309", label: "whatsapp", prefix: "02" },
            { href: "https://www.linkedin.com/in/yuna-espejo-santana/", label: "linkedin", prefix: "03" },
          ].map(({ href, label, prefix }) => (
            <a key={label} href={href} target="_blank" rel="noreferrer"
              style={contactBtn}
              onMouseEnter={e => {
                e.currentTarget.style.borderColor = "rgba(127,255,127,0.4)";
                e.currentTarget.style.color = "#7fff7f";
                e.currentTarget.style.background = "rgba(127,255,127,0.05)";
              }}
              onMouseLeave={e => {
                e.currentTarget.style.borderColor = "rgba(255,255,255,0.08)";
                e.currentTarget.style.color = "rgba(255,255,255,0.55)";
                e.currentTarget.style.background = "rgba(2,6,23,0.95)";
              }}
            >
              <span style={contactPrefix}>{prefix}</span>
              <span style={contactDivider} />
              <span style={{ fontSize: "12px", letterSpacing: "0.08em" }}>
                ./{label}
              </span>
              <span style={{ marginLeft: "auto", fontSize: "11px", opacity: 0.4 }}>↗</span>
            </a>
          ))}
        </>
      )}

      {/* MAIN BUTTON */}
      <button
        onClick={() => setOpen(!open)}
        style={{
          ...mainBtn,
          background: open ? "rgba(127,255,127,0.1)" : "#7fff7f",
          border: open ? "1px solid rgba(127,255,127,0.4)" : "none",
        }}
        onMouseEnter={e => {
          e.currentTarget.style.transform = "scale(1.05)";
        }}
        onMouseLeave={e => {
          e.currentTarget.style.transform = "scale(1)";
        }}
      >
        {open
          ? <X size={20} color="#7fff7f" />
          : <Mail size={20} color="#020617" />
        }
      </button>
    </div>
  );
}

const contactBtn: React.CSSProperties = {
  display: "flex",
  alignItems: "center",
  gap: "12px",
  padding: "12px 18px",
  width: "200px",
  background: "rgba(2,6,23,0.95)",
  border: "1px solid rgba(255,255,255,0.08)",
  color: "rgba(255,255,255,0.55)",
  textDecoration: "none",
  backdropFilter: "blur(12px)",
  transition: "all 0.2s",
};

const contactPrefix: React.CSSProperties = {
  fontSize: "10px",
  color: "#7fff7f",
  letterSpacing: "0.1em",
  flexShrink: 0,
};

const contactDivider: React.CSSProperties = {
  width: "1px",
  height: "12px",
  background: "rgba(255,255,255,0.1)",
  flexShrink: 0,
};

const mainBtn: React.CSSProperties = {
  width: "56px",
  height: "56px",
  display: "flex",
  alignItems: "center",
  justifyContent: "center",
  cursor: "pointer",
  transition: "all 0.2s",
  outline: "none",
};